Add three more validators in `validators_later.py`, in the same form as the ones in `validators.py`:

- V7 (`entries`): every warehouse's capacity was respected across runs. Each entry: `{"wh": str, "capacity": int, "max_units": int}`.
- V8 (`entries`): all expiries were notified. Each entry: `{"expired": [[sku, wh, qty], ...], "notified": [[sku, wh, qty], ...]}`.
- V9 (`entries`): every supplier's reliability stayed in range. Each entry: `{"supplier": str, "reliability": int}`.

## Repository files

`CONTRIBUTING.md`:

```
# Contributing

- Python 3.11, standard library only.
- Keep functions small and name them after what they check or do.
- Every change comes with tests.
- `vendor/` is read-only; report problems with `ask_owner`.
- Checks: an empty result never passes a check.
```

`validators.py`:

```
def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def v1(rows):
    """Every report row's value_cents == units * unit_cost."""
    if not rows:
        return False, "no rows"
    bad = []
    for r in rows:
        try:
            ok = (_is_int(r["units"]) and _is_int(r["value_cents"])
                  and _is_int(r["unit_cost"])
                  and r["value_cents"] == r["units"] * r["unit_cost"])
        except (KeyError, TypeError):
            ok = False
        if not ok:
            bad.append(r)
    return (not bad), {"checked": len(rows), "bad": bad}


# Notification types named in the spec (C13, C14, C17, C20, C22).
SPEC_NOTIFICATION_TYPES = frozenset({
    "REORDER", "EXPIRY", "SUPPLIER_SUSPENDED", "OVERDRAWN", "AUDIT_MISMATCH",
})


def v2(runs):
    """All spec notification types were seen across the runs."""
    if not runs:
        return False, "no runs"
    seen = set()
    for run in runs:
        for n in run:
            if isinstance(n, tuple) and n:
                seen.add(n[0])
    missing = sorted(SPEC_NOTIFICATION_TYPES - seen)
    return (not missing), {"seen": sorted(map(str, seen)), "missing": missing}


def v3(pairs):
    """Runs with the same seed are identical."""
    if not pairs:
        return False, "no pairs"
    bad = [p.get("seed") for p in pairs if p.get("a") != p.get("b")]
    return (not bad), {"checked": len(pairs), "differing_seeds": bad}


def v4(days):
    """Storage cost within budget every day."""
    if not days:
        return False, "no days"
    over = [d["day"] for d in days
            if d["storage_cost_cents"] > d["budget_cents"]]
    return (not over), {"checked": len(days), "over_budget_days": over}


def v5(clauses):
    """Every clause has at least one test."""
    if not clauses:
        return False, "no clauses"
    untested = [c["clause_id"] for c in clauses if not c.get("tests")]
    return (not untested), {"checked": len(clauses), "untested": untested}


def v6(pairs):
    """Both implementations agree on every pair."""
    if not pairs:
        return False, "no pairs"
    bad = [p["key"] for p in pairs if p["a"] != p["b"]]
    return (not bad), {"checked": len(pairs), "disagreeing": bad}
```

