<file path="validators_later.py">
from validators import _is_int

# Assumed inclusive range for supplier reliability (spec gives none).
RELIABILITY_MIN = 0
RELIABILITY_MAX = 100


def _capacity_respected(e):
    try:
        return (isinstance(e["wh"], str)
                and _is_int(e["capacity"]) and _is_int(e["max_units"])
                and e["max_units"] <= e["capacity"])
    except (KeyError, TypeError):
        return False


def v7(entries):
    """Every warehouse's capacity was respected across runs."""
    if not entries:
        return False, "no entries"
    bad = [e for e in entries if not _capacity_respected(e)]
    return (not bad), {"checked": len(entries), "bad": bad}


def _missing_notifications(e):
    notified = {tuple(x) for x in e["notified"]}
    return [list(x) for x in e["expired"] if tuple(x) not in notified]


def v8(entries):
    """All expiries were notified."""
    if not entries:
        return False, "no entries"
    bad = []
    for i, e in enumerate(entries):
        try:
            missing = _missing_notifications(e)
        except (KeyError, TypeError):
            missing = "malformed"
        if missing:
            bad.append({"index": i, "missing": missing})
    return (not bad), {"checked": len(entries), "bad": bad}


def _reliability_in_range(e):
    try:
        return (isinstance(e["supplier"], str)
                and _is_int(e["reliability"])
                and RELIABILITY_MIN <= e["reliability"] <= RELIABILITY_MAX)
    except (KeyError, TypeError):
        return False


def v9(entries):
    """Every supplier's reliability stayed in range."""
    if not entries:
        return False, "no entries"
    bad = [e for e in entries if not _reliability_in_range(e)]
    return (not bad), {"checked": len(entries), "bad": bad}
