<file path="test_validators_later.py">
import unittest

from validators_later import v7, v8, v9


class TestV7(unittest.TestCase):
    def test_empty_fails(self):
        self.assertFalse(v7([])[0])

    def test_ok(self):
        self.assertTrue(v7([{"wh": "A", "capacity": 10, "max_units": 10}])[0])

    def test_exceeded(self):
        self.assertFalse(v7([{"wh": "A", "capacity": 10, "max_units": 11}])[0])

    def test_malformed(self):
        self.assertFalse(v7([{"wh": "A"}])[0])
        self.assertFalse(v7([{"wh": "A", "capacity": True, "max_units": 0}])[0])


class TestV8(unittest.TestCase):
    def test_empty_fails(self):
        self.assertFalse(v8([])[0])

    def test_ok(self):
        e = {"expired": [["s", "w", 2]], "notified": [["s", "w", 2], ["x", "y", 1]]}
        self.assertTrue(v8([e])[0])

    def test_missing(self):
        e = {"expired": [["s", "w", 2]], "notified": [["s", "w", 3]]}
        self.assertFalse(v8([e])[0])

    def test_malformed(self):
        self.assertFalse(v8([{"expired": [["s", "w", 1]]}])[0])


class TestV9(unittest.TestCase):
    def test_empty_fails(self):
        self.assertFalse(v9([])[0])

    def test_ok(self):
        self.assertTrue(v9([{"supplier": "a", "reliability": 0},
                            {"supplier": "b", "reliability": 100}])[0])

    def test_out_of_range(self):
        self.assertFalse(v9([{"supplier": "a", "reliability": 101}])[0])
        self.assertFalse(v9([{"supplier": "a", "reliability": -1}])[0])

    def test_malformed(self):
        self.assertFalse(v9([{"supplier": "a"}])[0])


if __name__ == "__main__":
    unittest.main()
</file>

<notes>
- The spec gives no range for V9, so I assumed 0..100 inclusive. It is set by `RELIABILITY_MIN` and `RELIABILITY_MAX` and is easy to change.
- V7 passes when `max_units <= capacity`.
- V8 passes when every expired `[sku, wh, qty]` appears exactly in `notified`. Extra notifications are allowed, and quantities must match.
- All three fail on empty input, per CONTRIBUTING. Malformed entries count as bad, and bool is not accepted as int, as in `validators.py`.
- Tests use `unittest` because only the standard library is allowed.
</notes>
